head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.etp_Invstwarn_design_cd = "02"; // 지정예고
scwin.list_bz_tp_cd = "";
scwin.discls_form_cd = "";
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Isu_cd = "", scwin.Isu_nm = "", scwin.Secugrp_id = "", scwin.fr_bz_procs_no = "", scwin.design_dd = "", scwin.Inq_dd = "", scwin.today_dd = "", scwin.fst_dtect_dd = "", scwin.selectedGrdNum = 0;
scwin.trsCnt = 0, scwin.trsTotalCnt = 0, scwin.trsErrCnt = 0;
scwin.trsIdx;
scwin.getPar, scwin.setPar;

//

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar;
        const arrPar = new Array();
        fnc(arrPar);
        scwin.Isu_cd = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.Isu_nm = (arrPar.length >= 2 ? arrPar[1] : "");
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : "");
        Mkt_id = (arrPar.length >= 4 ? arrPar[3] : "");
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : "");
        scwin.design_dd = (arrPar.length >= 6 ? arrPar[5] : "");
        scwin.Inq_dd = (arrPar.length >= 7 ? arrPar[6] : "");
        scwin.fst_dtect_dd = (arrPar.length >= 8 ? arrPar[7] : "");
        scwin.Isur_cd = (arrPar.length >= 9 ? arrPar[8] : "");
        buttonSet.setSaveInfo(btn_Save, scwin.save);
        buttonSet.setUpdateInfo(btn_Update, scwin.update);
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete);
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl);
        scwin.setIsuCdBtnShow();
        await scwin.todayDate();
        await scwin.onload();
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        dts_Isu_Temp.setCellData(scwin.trsCnt, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "Y");
        if (scwin.trsCnt === scwin.trsTotalCnt) {
            $c.lce.fn_alertMsg('S');
            scwin.parentRefresh();
            if (dts_Isu_Temp.getRowCount() === 1) {
                scwin.selectGridRow(1);
            }
            if (buttonSet.status === "I") {
                buttonSet.setUpdateStatus();
                scwin.setIsuCdBtnShow();
            } else if (buttonSet.status === "D") {
                await $c.win.closePopup();
            } else {

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnFail = async function() {
    try {
        await $c.win.alert(trs);
        dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "N");
        scwin.trsErrCnt++;
        if (scwin.trsCnt === scwin.trsTotalCnt && scwin.trsErrCnt > 0) {
            $c.lce.fn_alertMsg('F');
            if (buttonSet.status === "D") {
                dts_Isu_Temp.setBroadcast(false);
                for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
                    if (dts_Isu_Temp.getCellData(i, "STATUS") === "Y") {
                        dts_Isu_Temp.removeRow(i);
                    }
                }
                dts_Isu_Temp.setBroadcast(true, true);
            } else {

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.trs_OnFail" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
            dts_Mst.insertRow();
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "DESIGN_DD", scwin.design_dd);
            txa_Rsn.Text = "적출일의 다음 매매거래일부터 10매매거래일 이내에 장종료시 실시간 괴리율이\r\n" + "규정상 관리의무 비율의 2배 이상에 해당";
            txa_InvstwarnContn.Text = "지정예고일로부터 10매매거래일 이내에 다시 적출되는 경우\r\n" + "다음 매매거래일부터 투자유의종목으로 지정될 수 있습니다.\r\n" + "투자유의종목으로 지정되는 경우 3매매거래일간 단일가매매가 시행됩니다.";
            txa_Remk.Text = "괴리율이 확대되는 등 투자유의가 필요한 종목은 \“적출->지정예고->지정\” 단계에 따라\r\n" + "투자유의종목으로 지정될 수 있습니다. 투자유의종목으로 지정 시 3매매거래일 단위로 단일가매매가 시행되고\r\n" + "매매거래가 정지될 수 있습니다. 단, 호가상황 및 매매거래상황 등에 따라 각 단계를 거치지 않고 지정될 수 있으며,\r\n" + "지정과 동시에 매매거래가 정지될 수 있습니다.";
        } else {
            $c.stf.copyDataSet(dts_Mst, dts_Isu_Temp);
            $c.stf.copyDataSet(dts_Mst, dts_Isu);
            scwin.Isur_cd = dts_Isu_Temp.getCellData(1, "ISUR_CD");
            scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(1, "BZ_PROCS_NO");
            scwin.setIsuCdBtnShow();
            if (scwin.Inq_dd < scwin.today_dd) {
                buttonSet.setDisableStatus();
            } else {
                buttonSet.setUpdateStatus();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadError
 * @description dts_Mst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Mst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        dts_Isu.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_Temp_OnLoadCompleted
 * @description dts_Isu_Temp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_Temp_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "" && scwin.Isu_cd !== "") {
            dts_Isu_Temp.insertRow();
            dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISU_CD", scwin.Isu_cd);
            dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISU_NM", scwin.Isu_nm);
            dts_Isu_Temp.setCellData(dts_Isu_Temp.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Isu_Temp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Isu_Temp_OnLoadError
 * @description dts_Isu_Temp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_Temp_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu_Temp);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Isu_Temp_OnLoadError" });
    }
};

/**
 * @method
 * @name img_SetIsuCd_onclick
 * @description 「종목선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsu;
        scwin.setPar = scwin.setParIsu;
        if (scwin.Secugrp_id === SECUGRP_ID_EN) {
            $c.lce.fn_PopFindEtnCode();
        } else if (scwin.Secugrp_id === SECUGRP_ID_EF) {
            $c.lce.fn_PopFindEtfCode(scwin.Secugrp_id);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_DesignDd_onclick
 * @description img_DesignDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DesignDd_onclick = function() {
    try {
        popUpCalendar2(edt_DesignDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.img_DesignDd_onclick" });
    }
};

/**
 * @method
 * @name grid_1_OnClick
 * @description grid_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grid_1_OnClick = function(row, colid) {
    try {
        scwin.selectGridRow(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08302.grid_1_OnClick" });
    }
};

/**
 * @method
 * @name dts_Cand_OnLoadError
 * @description dts_Cand 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cand_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Cand);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08302.dts_Cand_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onload = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/etn/EtnMktAct.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        url += "&SCREN_ID=" + "ULDSTF05342.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* useupdate를 false로 지정함. */
        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Isu.insertRow();
        const sbmOptions3 = {
            id : "sbm_dts_Isu_Temp",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu_Temp=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name todayDate
 * @description today Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.todayDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cand",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Cand=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.today_dd = dts_Cand.getCellData(1, "TODAY_DD");
};

/**
 * @method
 * @name saveTrs
 * @description save Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ETP_INVSTWARN_DESIGN_CD", scwin.etp_Invstwarn_design_cd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISU_CD", dts_Isu.getCellData(1, "ISU_CD"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", dts_Isu.getCellData(1, "ISUR_CD"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "FST_DESIGN_DD", scwin.fst_dtect_dd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADD_YN", dts_Isu.getCellData(1, "ADD_YN"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BAS_DD", scwin.Inq_dd);
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    if (scwin.Secugrp_id === SECUGRP_ID_EN) {
        scwin.list_bz_tp_cd = LIST_BZ_TP_CD_716;
    } else if (scwin.Secugrp_id === SECUGRP_ID_EF) {
        scwin.list_bz_tp_cd = LIST_BZ_TP_CD_750;
    }
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : scwin.list_bz_tp_cd + ",DIV_IDX[0]=" + DIV_IDX_ETN_INVSTWARN_MST
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/etn/EtnMktAct.do",
        ref : "dts_Mst",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name duplicateCheck
 * @description duplicate Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateCheck = async function() {
    let url = "";
    for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
        url += "&ETP_INVSTWARN_DESIGN_CD=" + scwin.etp_Invstwarn_design_cd;
        url += "&ISU_CD=" + dts_Isu_Temp.getCellData(i, "ISU_CD");
        url += "&BAS_DD=" + scwin.Inq_dd;
        const sbmOptions = {
            id : "sbm_dts_DUP_CHK",
            action : "/etn/EtnMktAct.do",
            ref : "",
            target : "dts_DUP_CHK=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (dts_DUP_CHK.getCellData(1, "DUP_CHK") === "Y") {
            await $c.win.alert("중복된 종목이 저장되어 있습니다.");
            return "Y";
        }
    }
    return "N";
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu_Temp.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if (edt_DesignDd.getValue() === "") {
        await $c.win.alert("[지정예고일]을 입력하세요.");
        edt_DesignDd.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name copyDts
 * @description copy Dts 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.copyDts = function(index) {
    if (dts_Isu.getRowCount() === 0) {
        dts_Isu.insertRow();
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu.setCellData(1, "ISU_CD", dts_Isu_Temp.getCellData(index, "ISU_CD"));
    dts_Isu.setCellData(1, "ISU_NM", dts_Isu_Temp.getCellData(index, "ISU_NM"));
    dts_Isu.setCellData(1, "ISUR_CD", dts_Isu_Temp.getCellData(index, "ISUR_CD"));
    dts_Isu.setCellData(1, "ADD_YN", dts_Isu_Temp.getCellData(index, "ADD_YN"));
    scwin.Isur_cd = dts_Isu_Temp.getCellData(index, "ISUR_CD");
    scwin.Isur_nm = dts_Isu_Temp.getCellData(index, "COM_NM");
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (await scwin.duplicateCheck() === "Y") {
            return;
        }
        if (!$c.lce.fn_isProcess('I')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getRowCount();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        dts_Isu_Temp.setBroadcast(false);
        for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
            scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
            scwin.copyDts(i);
            if (scwin.fr_bz_procs_no.length !== 14) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            } else {
                scwin.trsIdx = TRS_IDX_INSERT;
                dts_Isu_Temp.setCellData(i, "STATUS", "N");
                scwin.trsCnt++;
                await scwin.saveTrs();
            }
        }
        dts_Isu_Temp.setBroadcast(true, true);
    }
};

