/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (dts_Isu_Temp.getRowCount() > 1 && scwin.selectedGrdNum === 0) {
        await $c.win.alert('종목을 선택해 주세요.');
        return;
    } else if (dts_Isu_Temp.getRowCount() === 1) {
        scwin.selectedGrdNum = 1;
    }
    scwin.copyDts(scwin.selectedGrdNum);
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst) {
        if (scwin.Secugrp_id === SECUGRP_ID_EN) {
            scwin.discls_form_cd = "68390"; // 상장지수증권 투자유의종목 지정예고 안내공시

        } else if (scwin.Secugrp_id === SECUGRP_ID_EF) {
            scwin.discls_form_cd = "99356"; // ETF 투자유의종목 지정예고

        }
        arr[0] = scwin.discls_form_cd;
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        if (scwin.Secugrp_id === SECUGRP_ID_EN) {
            arr[5] = dts_Isu.getCellData(scwin.selectedGrdNum, "ISU_NM");
        } else if (scwin.Secugrp_id === SECUGRP_ID_EF) {
            arr[5] = "";
        }
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "COM_NM", dts_Isu_Temp.getCellData(scwin.selectedGrdNum, "COM_NM"));
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 15;
    const hgt = 785 + 40;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

